var ROUTE_FREQUENCY_MIN = {
  // ── Bus routes (NMMT) ────────────────────────────────────────────────────
  "Jaitala - Pardi": 20,
  "Jaripataka - Sonegaon": 20,
  "Khapri Metro Station - Tech Mahindra Mihan Sez": 30,
  "Khapri Metro Stattion - Mihan": 30,
  "Lokmanya nagr - Wadi -Tpoint": 20,
  "Maharaja Baug Terminal - Nirmal Nagar": 20,
  "Maharaja Baug Terminal - Sawarmendha": 25,
  "Maharaja Baug Terminal - Vaishnodevi Chowk": 15,
  "Panchasheel Chowk (Dhantoli) - C.R.P.F.Stand": 15,
  "Pardi - Y.C.C.E.College": 25,
  "Sitabuldi - Besa Chowk": 15,
  "Sitabuldi - Defence Gate No. 3": 20,
  "Sitabuldi - Koradi Depot": 20,
  "Sitabuldi - Pardi": 15,
  "Sitabuldi - Sonegaon": 15,
  "Sitabuldi - Suradevi": 20,
  "Sitabuldi - jaitala": 15,
  // ── Metro lines (Nagpur Metro) ────────────────────────────────────────────
  "Blue Line": 10,
  "Orange Line": 10
};
function getFrequencyMin(lineName) {
  return ROUTE_FREQUENCY_MIN[lineName] ?? 20;
}

// protected/src/lib/network.ts
var EARTH_R = 6371e3;
function haversine(aLat, aLon, bLat, bLon) {
  const toRad = (d) => d * Math.PI / 180;
  const dLat = toRad(bLat - aLat);
  const dLon = toRad(bLon - aLon);
  const s = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(aLat)) * Math.cos(toRad(bLat)) * Math.sin(dLon / 2) ** 2;
  return 2 * EARTH_R * Math.asin(Math.sqrt(s));
}
var norm = (s) => s.toLowerCase().replace(/[^a-z0-9 ]/g, " ").replace(/\s+/g, " ").trim();
var CLUSTER_M = 120;
var busSchedules = bus_schedules_default;
function buildNetwork(data = network_default) {
  const places = /* @__PURE__ */ new Map();
  const placeList = [];
  const byName = /* @__PURE__ */ new Map();
  function getPlace(stop, mode) {
    const key2 = norm(stop.name);
    const candidates = byName.get(key2) ?? [];
    for (const c of candidates) {
      if (haversine(c.lat, c.lon, stop.lat, stop.lon) <= CLUSTER_M) return c;
    }
    for (const p of placeList) {
      if (haversine(p.lat, p.lon, stop.lat, stop.lon) <= 40 && p.modes.has(mode)) return p;
    }
    const place = {
      id: `p${placeList.length}`,
      name: stop.name,
      lat: stop.lat,
      lon: stop.lon,
      modes: /* @__PURE__ */ new Set(),
      routes: /* @__PURE__ */ new Set()
    };
    places.set(place.id, place);
    placeList.push(place);
    byName.set(key2, [...candidates, place]);
    return place;
  }
  const lines = /* @__PURE__ */ new Map();
  data.bus.forEach((r, i) => {
    const id = `bus:${i}`;
    const sched = busSchedules[r.route.toLowerCase().trim()];
    const durationMin = sched?.durationMin || 45;
    const departures = sched?.departures || [];
    const validDeps = departures.filter((d) => d > 0 && d < 1439);
    const tripsPerDay = validDeps.length;
    let headwayMin = getFrequencyMin(r.route);
    if (tripsPerDay >= 2) {
      headwayMin = Math.max(5, Math.round((validDeps[tripsPerDay - 1] - validDeps[0]) / (tripsPerDay - 1)));
    } else if (tripsPerDay === 1) {
      headwayMin = 120;
    }
    const cumDist = [0];
    for (let sIdx = 1; sIdx < r.stops.length; sIdx++) {
      const prev = r.stops[sIdx - 1];
      const curr = r.stops[sIdx];
      const d = haversine(prev.lat, prev.lon, curr.lat, curr.lon) * 1.25;
      cumDist.push(cumDist[cumDist.length - 1] + d);
    }
    const totalDist = cumDist[cumDist.length - 1] || 1;
    const stopOffsets = cumDist.map(
      (d) => totalDist > 0 ? Number((d / totalDist * durationMin).toFixed(2)) : 0
    );
    const placeIds = r.stops.map((s) => {
      const p = getPlace(s, "bus");
      p.modes.add("bus");
      p.routes.add(id);
      return p.id;
    });
    lines.set(id, {
      id,
      mode: "bus",
      name: r.route,
      busNumber: r.bus_number || sched?.busNumber,
      durationMin,
      departures,
      tripsPerDay,
      headwayMin,
      stopOffsets,
      placeIds,
      points: r.stops,
      frequencyMin: headwayMin
    });
  });
  data.metro.forEach((l, i) => {
    const id = `metro:${i}`;
    const lineName = `${l.line} Line`;
    const placeIds = l.stations.map((s) => {
      const p = getPlace(s, "metro");
      p.modes.add("metro");
      p.routes.add(id);
      return p.id;
    });
    const cumDist = [0];
    for (let sIdx = 1; sIdx < l.stations.length; sIdx++) {
      const prev = l.stations[sIdx - 1];
      const curr = l.stations[sIdx];
      const d = haversine(prev.lat, prev.lon, curr.lat, curr.lon);
      cumDist.push(cumDist[cumDist.length - 1] + d);
    }
    const totalDist = cumDist[cumDist.length - 1] || 1;
    const isBlue = l.line.toLowerCase().includes("blue") || l.line.toLowerCase().includes("line 2") || l.line.toLowerCase().includes("aqua");
    const durationMin = isBlue ? 36 : 38;
    const stopOffsets = cumDist.map(
      (d) => totalDist > 0 ? Number((d / totalDist * durationMin).toFixed(2)) : 0
    );
    const headwayMin = 10;
    const departures = [];
    for (let t = 360; t <= 1350; t += headwayMin) {
      departures.push(t);
    }
    lines.set(id, {
      id,
      mode: "metro",
      name: lineName,
      placeIds,
      points: l.stations,
      durationMin,
      departures,
      tripsPerDay: departures.length,
      headwayMin,
      stopOffsets,
      frequencyMin: headwayMin
    });
  });
  return { places, lines, placeList };
}

